mapper.select:
SELECT FROM permissions
AND permission_name LIKE CONCAT('%', #{params.permissionName}, '%')
ORDER BY sort_order ASC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE permissions
permission_name = #{permissionName}, permission_code = #{permissionCode}, resource_type = #{resourceType}, parent_id = #{parentId}, sort_order = #{sortOrder},
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) > 0 FROM permissions

    AND id = #{params.id}
    AND permission_code = #{params.permissionCode}

SELECT DISTINCT p.* FROM permissions p INNER JOIN role_permissions rp ON p.id = rp.permission_id WHERE rp.role_id IN
#{roleId}
ORDER BY p.sort_order ASC
